local ESP = Window:AddTab("ESP")
ESP:AddMasterToggle("esp_enabled", { Text = "ESP", Default = true, Tooltip = "Master switch for all ESP: players, gun and coins" })

local EspPlayers = ESP:AddGroup("Players", "Left")
