EspStyle:AddSlider("esp_fill", { Text = "Fill Opacity", Min = 0, Max = 100, Default = 0, Suffix = "%", Tooltip = "0 = outline only" })
EspStyle:AddToggle("esp_walls", { Text = "Show Through Walls", Default = true })
EspStyle:AddLabel("Red = murderer, blue = sheriff, gold = hero, green = innocent.", { Color = Library.Theme.TextDim })
if not hasDrawing then
	EspStyle:AddLabel("Tracers need the Drawing library, which this environment doesn't have.", { Color = Library.Theme.TextDim })
end

local EspItems = ESP:AddGroup("Items", "Right")
EspItems:AddToggle("gun_esp", { Text = "Dropped Gun", Default = true })
EspItems:AddToggle("coin_esp", { Text = "Coins", Callback = function(v) if not v then clearCoinEsp() end end })

local busy = false        -- true while a fling is driving the character

loader:Step("Hooking combat and aim assist...")
------------------------------------------------------------------------
-- Combat. Names and arguments come from a remote capture:
--   gun:   Gun.Shoot:FireServer(rootCFrame, CFrame.new(aimPosition))
--   throw: Knife.Events.KnifeThrown:FireServer(CFrame, CFrame.new(aimPosition))
--   stab:  Knife.Events.KnifeStabbed:FireServer(), then Knife.Events.HandleTouched:FireServer(part)
--          for every part the blade touched (the client reports its own hits)
-- Wrapped in do ... end: a Lua chunk holds at most 200 live locals and nothing outside this tab
-- needs these helpers. Do the same for the next tabs.
------------------------------------------------------------------------
do
	local GENV = (typeof(getgenv) == "function" and getgenv()) or _G
	local GUN_COOLDOWN = 3     -- seconds between shots; the server reloads the gun and ignores early ones
	local KNIFE_COOLDOWN = 0.5 -- seconds between swings (aura, kill all)
	local hookReady = typeof(hookmetamethod) == "function" and typeof(getnamecallmethod) == "function"

	local lastGunShot, lastStab = 0, 0
	local Aim = { gun = nil, throw = nil } -- where redirected shots go, refreshed every frame

	------------------------------------------------------------------
	-- helpers
	------------------------------------------------------------------
	-- equip and wait until the tool is in the character (its remotes only work from there)
	local function equip(tool)
		local h = myHum()
		if not (tool and h) then return false end
		if tool.Parent ~= LP.Character then
			h:EquipTool(tool)
			local t0 = os.clock()
			while tool.Parent ~= LP.Character and os.clock() - t0 < 0.4 do task.wait() end
		end
		return tool.Parent == LP.Character
	end

	-- Where to aim at a player: head or torso, led to where they will be when the shot is judged.
	-- The lead covers the trip to the server plus the delay in what we see (ping + 80ms, measured
	-- live). It uses their velocity, a smoothed acceleration from the last few frames, and gravity
	-- while they're in the air. Nothing is certain if they change direction inside that window.
	local Stats = game:GetService("Stats")
	local leadTime = 0.15
	task.spawn(function()
		while running() do
			local ok, ms = pcall(function() return Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
			if not (ok and type(ms) == "number" and ms > 0) then ms = 100 end
			leadTime = math.clamp(ms / 1000 + 0.08, 0.06, 0.7)
			task.wait(0.25)
		end
	end)

	local motion = {} -- per player: last velocity, smoothed acceleration, and when it was sampled
	on(Players.PlayerRemoving, function(p) motion[p] = nil end)

	local function leadOffset(p, root, hum)
		local now = os.clock()
		local v = root.AssemblyLinearVelocity
		local m = motion[p]
		if not m or now - m.t > 0.5 then
			m = { v = v, a = Vector3.zero, t = now }
			motion[p] = m
		elseif now - m.t >= 0.008 then
			-- one frame of acceleration is mostly noise, so smooth it
			m.a = m.a:Lerp((v - m.v) / (now - m.t), 0.25)
			m.v, m.t = v, now
		end
		local t = leadTime
		local flat = Vector3.new(v.X, 0, v.Z) * t + Vector3.new(m.a.X, 0, m.a.Z) * (0.25 * t * t)
		local rise = 0
		if hum and hum.FloorMaterial == Enum.Material.Air then
			rise = v.Y * t - 0.5 * workspace.Gravity * t * t
		end
		local offset = Vector3.new(flat.X, rise, flat.Z)
		if offset.Magnitude > 30 then offset = offset.Unit * 30 end
		return offset
	end

	local function aimPoint(p, partName)
		local c = p and p.Character
		local root = c and c:FindFirstChild("HumanoidRootPart")
		if not root then return nil end
		local part = (partName == "Head" and c:FindFirstChild("Head"))
			or c:FindFirstChild("UpperTorso") or c:FindFirstChild("Torso") or root
		return part.Position + leadOffset(p, root, c:FindFirstChildOfClass("Humanoid"))
	end

	-- the player nearest the cursor (anyone off screen ranks behind everyone on screen)
	local function closestToCursor()
		local camera = cam()
		local mouse = UIS:GetMouseLocation()
		local me = myRoot()
		local best, bestScore
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= LP and inRound(p) then
				local r = rootOf(p)
				local pos, onScreen = camera:WorldToViewportPoint(r.Position)
				local score
				if onScreen then
					score = (Vector2.new(pos.X, pos.Y) - mouse).Magnitude
				elseif me then
					score = 1e5 + (r.Position - me.Position).Magnitude
				end
				if score and (not bestScore or score < bestScore) then best, bestScore = p, score end
			end
		end
		return best
	end

	local function hasSight(p)
		local me = LP.Character
		local head = me and me:FindFirstChild("Head")
		local r = rootOf(p)
		if not (head and r) then return false end
		local params = RaycastParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { me, p.Character, espFolder }
		params.RespectCanCollide = true -- coins, effects and other non-solid parts don't block a shot
		return workspace:Raycast(head.Position, r.Position - head.Position, params) == nil
	end

	------------------------------------------------------------------
	-- sheriff
	------------------------------------------------------------------
	local function fireGun(pos)
		local gun = hasTool(LP, "Gun")
		local shoot = gun and gun:FindFirstChild("Shoot")
		local root = myRoot()
		if not (shoot and root) then return false, "you don't have the gun" end
		if not equip(gun) then return false, "couldn't equip the gun" end
		lastGunShot = os.clock()
		shoot:FireServer(root.CFrame, CFrame.new(pos))
		return true
	end

	-- returns true, or false and why not
	local function shootMurderer(needSight)
		if os.clock() - lastGunShot < GUN_COOLDOWN then return false, "the gun is reloading" end
		if not hasTool(LP, "Gun") then return false, "you don't have the gun" end
		local m = findRole("Murderer")
		if not m then return false, "no murderer to shoot" end
		if needSight and not hasSight(m) then return false, "no line of sight" end
		local pos = aimPoint(m, Flags.aim_target)
		if not pos then return false, "the murderer has no character" end
		return fireGun(pos)
	end

	------------------------------------------------------------------
	-- murderer
	------------------------------------------------------------------
	-- one swing, the way the real client sends it: KnifeStabbed once, then HandleTouched per hit
	local function stab(knife, victims)
		local events = knife and knife:FindFirstChild("Events")
		local stabbed = events and events:FindFirstChild("KnifeStabbed")
		local touched = events and events:FindFirstChild("HandleTouched")
		if not (stabbed and touched) then return false end
		lastStab = os.clock()
		stabbed:FireServer()
		for _, p in ipairs(victims) do
			local c = p.Character
			local root = c and c:FindFirstChild("HumanoidRootPart")
			local torso = c and c:FindFirstChild("UpperTorso")
			if root then touched:FireServer(root) end
			if torso then touched:FireServer(torso) end
		end
		return true
	end

	local function knifeAura()
		if os.clock() - lastStab < KNIFE_COOLDOWN then return end
		local me, knife = myRoot(), hasTool(LP, "Knife")
		if not (me and knife) then return end
		local victims, range = {}, Flags.aura_range or 12
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= LP and inRound(p) and (rootOf(p).Position - me.Position).Magnitude <= range then
				table.insert(victims, p)
			end
		end
		if #victims == 0 then return end
		if knife.Parent ~= LP.Character and not (Flags.auto_equip and equip(knife)) then return end
		stab(knife, victims)
	end

	local function aliveOthers()
		local list = {}
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= LP and inRound(p) then table.insert(list, p) end
		end
		return list
	end

	-- the aura with no range: one swing with every living player in it, wherever they are.
	-- A couple of follow-up swings catch anyone the first one missed. No teleporting.
	local killing = false
	local function killAll()
		if killing then return end
		if not Flags.combat_enabled then notify("Combat is switched off.") return end
		local knife = hasTool(LP, "Knife")
		if not knife then notify("You're not the murderer.") return end
		local victims = aliveOthers()
		local total = #victims
		if total == 0 then notify("Nobody to kill.") return end
		if not equip(knife) then notify("Couldn't equip the knife.") return end
		killing = true
		for _ = 1, 3 do
			local wait = KNIFE_COOLDOWN - (os.clock() - lastStab)
			if wait > 0 then task.wait(wait) end
			stab(knife, victims)
			task.wait(0.35)
			victims = aliveOthers()
			if #victims == 0 then break end
		end
		killing = false
		notify(string.format("Kill All: %d of %d down.", total - #victims, total))
	end

	------------------------------------------------------------------
	-- aim redirect: silent aim (gun) and throw assist (knife)
	------------------------------------------------------------------
	-- refreshed every frame. The hook below only READS these: it runs inside every network call in
	-- the game, and a method call in there would overwrite the namecall the original is about to use.
	local function updateAim()
		Aim.gun, Aim.throw = nil, nil
		if not Flags.combat_enabled then return end
		if Flags.silent_aim then
			local m = findRole("Murderer")
			if m then Aim.gun = aimPoint(m, Flags.aim_target) end
		end
		if Flags.throw_assist then
			local t = closestToCursor()
			if t then Aim.throw = aimPoint(t, "HumanoidRootPart") end
		end
	end

	-- property reads only, no method calls (see above). Returns true if the arguments were changed.
	local function redirect(remote, args)
		if args.n < 2 or typeof(args[2]) ~= "CFrame" then return false end
		local name = remote.Name
		if name == "Shoot" then
			local tool = remote.Parent
			if tool and tool.Name == "Gun" and tool.Parent == LP.Character then
				lastGunShot = os.clock() -- your own shots start the reload too
				local pos = Aim.gun
				if pos and math.random(1, 100) <= (Flags.hit_chance or 100) then
					args[2] = CFrame.new(pos)
					return true
				end
			end
		elseif name == "KnifeThrown" then
			local events = remote.Parent
			local tool = events and events.Parent
			if tool and tool.Name == "Knife" and tool.Parent == LP.Character then
				local pos = Aim.throw
				if pos then
					args[2] = CFrame.new(pos)
					return true
				end
			end
		end
		return false
	end

	if hookReady then
		GENV.__xpware_redirect = redirect
		onUnload(function()
			if GENV.__xpware_redirect == redirect then GENV.__xpware_redirect = nil end
		end)
		-- installed once per session; a re-run just swaps the function the hook calls
		if not GENV.__xpware_hooked then
			GENV.__xpware_hooked = true
			local wrap = typeof(newcclosure) == "function" and newcclosure or function(f) return f end
			local isOurs = typeof(checkcaller) == "function" and checkcaller or function() return false end
			local setMethod = typeof(setnamecallmethod) == "function" and setnamecallmethod or nil
			local getMethod = getnamecallmethod
			local old
			old = hookmetamethod(game, "__namecall", wrap(function(self, ...)
				local method = getMethod()
				if method == "FireServer" then
					local fn = GENV.__xpware_redirect
					if fn and not isOurs() then
						local args = table.pack(...)
						local ok, changed = pcall(fn, self, args)
						if setMethod then setMethod(method) end
						if ok and changed then return old(self, table.unpack(args, 1, args.n)) end
					end
				end
				return old(self, ...)
			end))
		end
	end

	------------------------------------------------------------------
	-- loops
	------------------------------------------------------------------
	on(RunService.RenderStepped, updateAim)

	task.spawn(function()
		local lastErr
		while running() do
			if Flags.combat_enabled and not busy and inRound(LP) then
				local ok, err = pcall(function()
					if Flags.auto_shoot then shootMurderer(true) end
					if Flags.knife_aura then knifeAura() end
				end)
				if not ok and err ~= lastErr then
					lastErr = err
					warn("[xpware] combat: " .. tostring(err))
				end
			end
			task.wait(0.1)
		end
	end)

	------------------------------------------------------------------
	-- tab
	------------------------------------------------------------------
	local Combat = Window:AddTab("Combat")
	Combat:AddMasterToggle("combat_enabled", { Text = "Combat", Default = true, Tooltip = "Master switch for every combat feature" })

	local SheriffBox = Combat:AddGroup("Sheriff", "Left")
	SheriffBox:AddToggle("silent_aim", { Text = "Silent Aim", Tooltip = "Gun shots land on the murderer wherever you click", Callback = function(v)
		if v and not hookReady then
			notify("Silent aim needs hookmetamethod, which this executor doesn't have. Auto Shoot and the shoot key still work.", nil, 6)
		end
	end })
	SheriffBox:AddSlider("hit_chance", { Text = "Hit Chance", Min = 0, Max = 100, Default = 100, Suffix = "%", Tooltip = "Silent Aim only: how often a shot gets redirected" })
	SheriffBox:AddDropdown("aim_target", { Text = "Aim Part", Values = { "Head", "Torso" }, Default = "Torso",
		Tooltip = "Where shots land. The lead for movement, ping and jumps is automatic" })
	SheriffBox:AddToggle("auto_shoot", { Text = "Auto Shoot Murderer", Tooltip = "Shoots as soon as you have line of sight. Works without Silent Aim." })
	SheriffBox:AddKeybind("shoot_key", { Text = "Shoot Murderer", Default = Enum.KeyCode.E, Callback = function()
		if not Flags.combat_enabled then notify("Combat is switched off.", nil, 2) return end
		local ok, why = shootMurderer(false)
		if not ok and why then notify("Can't shoot: " .. why .. ".", nil, 2) end
	end })

	local MurdererBox = Combat:AddGroup("Murderer", "Right")
	MurdererBox:AddToggle("knife_aura", { Text = "Knife Aura", Tooltip = "Stabs everyone inside the range slider" })
	MurdererBox:AddSlider("aura_range", { Text = "Aura Range", Min = 5, Max = 25, Default = 12, Suffix = " studs" })
	MurdererBox:AddToggle("auto_equip", { Text = "Auto Equip Knife", Default = true, Tooltip = "Pulls the knife out when the aura needs it" })
	MurdererBox:AddToggle("throw_assist", { Text = "Throw Assist", Tooltip = "Knife throws hit whoever's closest to your cursor", Callback = function(v)
		if v and not hookReady then
			notify("Throw assist needs hookmetamethod, which this executor doesn't have.", nil, 6)
		end
	end })
	MurdererBox:AddDivider()
	State.actions.killAll = killAll
	MurdererBox:AddButton({ Text = "Kill All", Tooltip = "Stabs everyone alive at once, wherever they are", Callback = killAll })
end

loader:Step("Setting up teleports and gun tracking...")
------------------------------------------------------------------------
-- Teleport
------------------------------------------------------------------------
local Teleport = Window:AddTab("Teleport")

local Places = Teleport:AddGroup("Places", "Left")
Places:AddButton({ Text = "Lobby", Callback = tpLobby })
Places:AddButton({ Text = "Map", Callback = tpMap })
Places:AddButton({ Text = "Dropped Gun", Callback = tpGun })
Places:AddDivider()
Places:AddToggle("safe_spot", { Text = "Safe Spot", Tooltip = "Parks you on a platform 300 studs up. Turn off to go back.", Callback = setSafeSpot })
Places:AddKeybind("safe_spot_key", { Text = "Safe Spot Key", Default = Enum.KeyCode.Z, Callback = function()
	Options.safe_spot:Set(not Flags.safe_spot)
end })
Places:AddToggle("click_tp", { Text = "Ctrl + Click Teleport" })

local ToPlayer = Teleport:AddGroup("Players", "Right")
local tpTarget = ToPlayer:AddDropdown("tp_target", { Text = "Player", Values = otherNames() })
ToPlayer:AddButton({ Text = "Teleport To Player", Callback = function()
	local p = findPlayer(Flags.tp_target)
	if p then tpPlayer(p, "Player") else notify("Pick a player first.") end
end })
ToPlayer:AddButton({ Text = "Teleport To Murderer", Callback = function() tpPlayer(findRole("Murderer"), "Murderer") end })
ToPlayer:AddButton({ Text = "Teleport To Sheriff", Callback = function() tpPlayer(findSheriff(), "Sheriff") end })

-- dropped gun: picked up by touching Workspace.<Map>.GunDrop
do
	local grabbing = false
	local triedGun, tries = nil, 0 -- give up on a gun after a couple of failed attempts

	-- returns true if we ended up holding the gun; `manual` says why it didn't happen
	local function grabGun(manual)
		local function why(msg) if manual then notify(msg) end return false end
		if grabbing then return false end
		local gun = partOf(State.gun)
		if not gun then return why("The gun isn't dropped.") end
		if hasTool(LP, "Gun") then return why("You already have the gun.") end
		if roleOf(LP) == "Murderer" then return why("The murderer can't pick up the gun.") end
		local me = myRoot()
		if not (me and inRound(LP)) then return why("You need to be alive in the round.") end

		grabbing = true
		local home = me.CFrame
		local canTouch = typeof(firetouchinterest) == "function"
		local function got() return hasTool(LP, "Gun") ~= nil end
		local function touchGun()
			local r = myRoot()
			if canTouch and r and gun.Parent then
				pcall(firetouchinterest, r, gun, 0)
				pcall(firetouchinterest, r, gun, 1)
			end
		end
		local function waitFor(seconds)
			local t0 = os.clock()
			while os.clock() - t0 < seconds and gun.Parent and not got() do RunService.Heartbeat:Wait() end
		end

		-- 1) touch it from right where you stand: no travelling at all, like a kill aura but for the gun
		local dist = (gun.Position - me.Position).Magnitude
		local how
		touchGun()
		waitFor(0.15)
		if got() then
			how = string.format("from %d studs away", dist)
		else
			-- 2) the server wants you at it: snap onto it (one jump, no gliding) and touch every frame
			local snapped = true
			local t0 = os.clock()
			while os.clock() - t0 < 1.0 and gun.Parent and not got() and myRoot() do
				teleport(gun.CFrame + Vector3.new(0, 2.5, 0), true)
				touchGun()
				RunService.Heartbeat:Wait()
			end
			how = "after snapping onto it"
			if snapped and Flags.gun_return and myRoot() then teleport(home, true) end
		end
		local ok = got()
		grabbing = false
		notify(ok and ("Grabbed the gun " .. how .. ".") or "Couldn't pick up the gun.", "Gun", 3)
		return ok
	end

	task.spawn(function()
		while running() do
			local gun = State.gun
			if Flags.grab_gun and gun and gun.Parent and not grabbing then
				if gun ~= triedGun then triedGun, tries = gun, 0 end
				if tries < 4 and not hasTool(LP, "Gun") and roleOf(LP) ~= "Murderer" and inRound(LP) then
					tries += 1
					pcall(grabGun, false)
				end
			end
			RunService.Heartbeat:Wait() -- every frame, so the gun is ours the moment it lands
		end
	end)

	local GunBox = Teleport:AddGroup("Dropped Gun", "Left")
	GunBox:AddToggle("grab_gun", { Text = "Auto Grab Gun", Tooltip = "Grabs the gun the moment it drops. Touches it from where you stand first, and only snaps onto it if that isn't enough" })
	GunBox:AddToggle("gun_return", { Text = "Return After Grabbing", Default = true, Tooltip = "Takes you back to where you were, if you had to snap onto the gun" })
	GunBox:AddToggle("gun_notify", { Text = "Notify When Dropped", Default = true, Tooltip = "Pops a notification when the sheriff drops the gun" })
	State.actions.grabGun = function() grabGun(true) end
	GunBox:AddButton({ Text = "Grab Gun Now", Callback = function() grabGun(true) end })
end

loader:Step("Preparing trolling tools...")
------------------------------------------------------------------------
-- Trolling
------------------------------------------------------------------------
do
	local Trolling = Window:AddTab("Trolling")

	local function target() return findPlayer(Flags.troll_target) end

	-- Target fling, the way the well-known fling scripts do it: snap onto the target every frame
	-- with enormous velocity and spin, so the collision throws THEM. The old version spun our own
	-- body and had no protection, so it threw us instead and we fell into the void. Now:
	--   - the void-kill height is switched off while it runs
	--   - a zero-velocity BodyVelocity holds us in place between the snaps
	--   - the camera watches the target, not our own body
	--   - afterwards every part's velocity is zeroed each frame while we're put back home
	-- busy pauses noclip, anti-fling, follow/orbit and the farm meanwhile (they'd all get in the way).
	local HUGE_V = Vector3.new(9e7, 9e8, 9e7)
	local HUGE_R = Vector3.new(9e8, 9e8, 9e8)

	local function fling(p, label)
		if busy or p == LP then return end
		local c, me, h = LP.Character, myRoot(), myHum()
		local tc, th = p and p.Character, humOf(p)
		if not (tc and th and rootOf(p)) then notify(label .. " not found.") return end
		if not (c and me and h) then notify("You don't have a character right now.") return end

		busy = true
		local home = me.CFrame
		local oldDestroyHeight = workspace.FallenPartsDestroyHeight
		local bv
		local landed = false

		local ok, err = pcall(function()
			pcall(function() workspace.FallenPartsDestroyHeight = 0 / 0 end)
			h:SetStateEnabled(Enum.HumanoidStateType.Seated, false)
			cam().CameraSubject = th

			bv = Instance.new("BodyVelocity")
			bv.Velocity = Vector3.zero
			bv.MaxForce = Vector3.new(9e9, 9e9, 9e9)
			bv.Parent = me

			-- one placement: on top of the target (a little ahead of where they're heading), spun
			-- to a new angle, with the huge velocities set for this physics step
			local function snap(base, offset, angle)
				local v = base.AssemblyLinearVelocity
				local lead = Vector3.new(v.X, 0, v.Z) * 0.12
				c:PivotTo(CFrame.new(base.Position + lead) * offset * CFrame.Angles(math.rad(angle), 0, 0))
				me.AssemblyLinearVelocity = HUGE_V
				me.AssemblyAngularVelocity = HUGE_R
			end

			local angle, t0 = 0, os.clock()
			while running() and os.clock() - t0 < 2.5 do
				local base = rootOf(p)
				if not (base and p.Parent and p.Character == tc and c.Parent) then break end
				if th.Health <= 0 or h.Health <= 0 or th.Sit then break end
				if base.AssemblyLinearVelocity.Magnitude > 500 then landed = true break end -- they're gone
				angle += 100
				snap(base, CFrame.new(0, 1.5, 0), angle)
				task.wait()
				snap(base, CFrame.new(0, -1.5, 0), angle)
				task.wait()
				snap(base, CFrame.new(2, 1.5, 0), angle)
				task.wait()
				snap(base, CFrame.new(-2, -1.5, 0), angle)
				task.wait()
			end
		end)

		-- always runs, even if something above errored
		if bv then bv:Destroy() end
		pcall(function() h:SetStateEnabled(Enum.HumanoidStateType.Seated, true) end)
		if c.Parent and myRoot() then
			-- back home, zeroing every velocity each frame until the physics has settled
			for _ = 1, 15 do
				c:PivotTo(home + Vector3.new(0, 0.5, 0))
				for _, d in ipairs(c:GetDescendants()) do
					if d:IsA("BasePart") then
						d.AssemblyLinearVelocity = Vector3.zero
						d.AssemblyAngularVelocity = Vector3.zero
					end
				end
				pcall(function() h:ChangeState(Enum.HumanoidStateType.GettingUp) end)
				task.wait()
			end
		end
		local mine = (h.Parent and h) or myHum()
		if mine then cam().CameraSubject = mine end
		pcall(function() workspace.FallenPartsDestroyHeight = oldDestroyHeight end)
		busy = false

		if not ok then notify("Fling stopped: " .. tostring(err)) return end
		notify(landed and ("Flung " .. p.DisplayName .. ".") or ("The fling didn't land on " .. p.DisplayName .. "."))
	end

	local function chat(msg)
		local sent = pcall(function()
			local channels = game:GetService("TextChatService"):FindFirstChild("TextChannels")
			local general = channels and channels:FindFirstChild("RBXGeneral")
			assert(general, "no RBXGeneral channel")
			general:SendAsync(msg)
		end)
		if sent then return true end
		return (pcall(function() -- older games still use the legacy chat
			ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(msg, "All")
		end))
	end

	local function announceRoles()
		local m = anyoneWith("Murderer")
		local s = anyoneWith("Sheriff") or anyoneWith("Hero")
		if not (m or s) then notify("Roles aren't known yet.") return end
		local msg = string.format("Murderer: %s | Sheriff: %s", m and m.DisplayName or "?", s and s.DisplayName or "?")
		if not chat(msg) then notify("Couldn't send the chat message.") end
	end

	-- spectate: the camera follows the target until it's turned off, then comes back to you
	local spectating = false
	local function stopSpectate()
		if not spectating then return end
		spectating = false
		local h = myHum()
		if h then cam().CameraSubject = h end
	end
	onUnload(stopSpectate)
	on(RunService.RenderStepped, function()
		local th = humOf(target())
		if Flags.spectate and th then
			if cam().CameraSubject ~= th then cam().CameraSubject = th end
			spectating = true
		else
			stopSpectate()
		end
	end)

	-- follow / orbit (orbit wins if both are on)
	local orbitAngle = 0
	on(RunService.Heartbeat, function(dt)
		if busy or not (Flags.follow or Flags.orbit) then return end
		local me, tr = myRoot(), rootOf(target())
		if not (me and tr) then return end
		if Flags.orbit then
			orbitAngle += dt * (Flags.orbit_speed or 5) * 0.6
			local pos = tr.Position + Vector3.new(math.cos(orbitAngle), 0, math.sin(orbitAngle)) * (Flags.orbit_radius or 6)
			me.CFrame = CFrame.lookAt(pos, tr.Position)
		else
			me.CFrame = tr.CFrame * CFrame.new(0, 0, 3)
		end
		me.AssemblyLinearVelocity = Vector3.zero
	end)

	local TargetBox = Trolling:AddGroup("Target", "Left")
	local trollTarget = TargetBox:AddDropdown("troll_target", { Text = "Player", Values = otherNames() })
	TargetBox:AddToggle("spectate", { Text = "Spectate", Tooltip = "Your camera follows the target" })
	TargetBox:AddToggle("follow", { Text = "Follow", Tooltip = "Stick right behind the target" })
	TargetBox:AddToggle("orbit", { Text = "Orbit", Tooltip = "Circle around the target (wins over Follow)" })
	TargetBox:AddSlider("orbit_speed", { Text = "Orbit Speed", Min = 1, Max = 20, Default = 5 })
	TargetBox:AddSlider("orbit_radius", { Text = "Orbit Radius", Min = 3, Max = 20, Default = 6, Suffix = " studs" })

	local FlingBox = Trolling:AddGroup("Fling", "Right")
	FlingBox:AddButton({ Text = "Fling Target", Callback = function()
		local p = target()
		if p then fling(p, "Target") else notify("Pick a target first.") end
	end })
	State.actions.flingMurderer = function() fling(findRole("Murderer"), "Murderer") end
	State.actions.flingSheriff = function() fling(findSheriff(), "Sheriff") end
	FlingBox:AddButton({ Text = "Fling Murderer", Callback = function() fling(findRole("Murderer"), "Murderer") end })
	FlingBox:AddButton({ Text = "Fling Sheriff", Callback = function() fling(findSheriff(), "Sheriff") end })

	local ChatBox = Trolling:AddGroup("Chat", "Right")
	ChatBox:AddButton({ Text = "Announce Roles In Chat", Tooltip = "Says who the murderer and sheriff are in chat", Callback = announceRoles })

	-- keep both player dropdowns in sync with who's in the server
	local function refreshPlayerLists()
		local names = otherNames()
		tpTarget:SetValues(names)
		trollTarget:SetValues(names)
	end
	on(Players.PlayerAdded, refreshPlayerLists)
	on(Players.PlayerRemoving, function(p)
		removeEsp(p)
		task.defer(refreshPlayerLists)
	end)
end

loader:Step("Loading player utilities...")
------------------------------------------------------------------------
-- Player
------------------------------------------------------------------------
do
	local PlayerTab = Window:AddTab("Player")
	local DEFAULT_SPEED, DEFAULT_JUMP = 16, 50

	-- only overridden while a slider is off its default, so the game is left alone otherwise
	on(RunService.Heartbeat, function()
		local h = myHum()
		if not h then return end
		local ws, jp = Flags.walkspeed or DEFAULT_SPEED, Flags.jumppower or DEFAULT_JUMP
		if ws ~= DEFAULT_SPEED and h.WalkSpeed ~= ws then h.WalkSpeed = ws end
		if jp ~= DEFAULT_JUMP and (not h.UseJumpPower or h.JumpPower ~= jp) then
			h.UseJumpPower = true
			h.JumpPower = jp
		end
	end)

	on(UIS.JumpRequest, function()
		if not Flags.inf_jump then return end
		local h = myHum()
		if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end
	end)

	-- noclip (also used by the coin farm through forceNoclip). Paused during a fling: it needs collisions.
	local noclipped = {}
	local function restoreCollisions()
		for part in pairs(noclipped) do
			if part.Parent then part.CanCollide = true end
		end
		noclipped = {}
	end
	on(RunService.Stepped, function()
		local c = LP.Character
		if (Flags.noclip or forceNoclip) and not busy and c then
			for _, part in ipairs(c:GetDescendants()) do
				if part:IsA("BasePart") and part.CanCollide then
					noclipped[part] = true
					part.CanCollide = false
				end
			end
		elseif next(noclipped) then
			restoreCollisions()
		end
	end)
	onUnload(restoreCollisions)
	on(LP.CharacterAdded, function() noclipped = {} end)

	-- anti fling: other players' parts can't collide with us, so they can't push or fling us
	on(RunService.Stepped, function()
		if not Flags.anti_fling or busy then return end
		for _, p in ipairs(Players:GetPlayers()) do
			if p ~= LP and p.Character then
				for _, part in ipairs(p.Character:GetDescendants()) do
					if part:IsA("BasePart") and part.CanCollide then part.CanCollide = false end
				end
			end
		end
	end)

	local Movement = PlayerTab:AddGroup("Movement", "Left")
	Movement:AddSlider("walkspeed", { Text = "WalkSpeed", Min = 16, Max = 100, Default = 16, Callback = function(v)
		local h = myHum(); if h then h.WalkSpeed = v end
	end })
	Movement:AddSlider("jumppower", { Text = "JumpPower", Min = 50, Max = 200, Default = 50, Callback = function(v)
		local h = myHum(); if h then h.UseJumpPower = true; h.JumpPower = v end
	end })
	Movement:AddToggle("inf_jump", { Text = "Infinite Jump", Tooltip = "Jump again in mid-air" })
	Movement:AddToggle("noclip", { Text = "Noclip", Tooltip = "Walk through walls" })
	Movement:AddToggle("anti_fling", { Text = "Anti Fling", Tooltip = "Other players can't push or fling you" })
end

loader:Step("Starting server and misc tools...")
------------------------------------------------------------------------
-- Misc
------------------------------------------------------------------------
do
	local Misc = Window:AddTab("Misc")
	local TeleportService = game:GetService("TeleportService")
	local GuiService = game:GetService("GuiService")

	local RolesBox = Misc:AddGroup("Roles", "Left")
	RolesBox:AddToggle("role_notify", { Text = "Role Notifier", Default = true, Tooltip = "Tells you who the murderer and sheriff are each round" })
	local murdererLabel = RolesBox:AddLabel("Murderer: -")
	local sheriffLabel = RolesBox:AddLabel("Sheriff: -")
	local myRoleLabel = RolesBox:AddLabel("You: -")

	-- who has already been announced this round. Only forgotten once the round is really over
	-- (nobody holds a role for a few seconds): the murderer can die while the hero is still alive,
	-- and resetting then re-announced the hero every tick.
	local announced = {}
	local emptySince
	task.spawn(function()
		while running() do
			local m = anyoneWith("Murderer")
			local s = anyoneWith("Sheriff") or anyoneWith("Hero")
			murdererLabel:Set("Murderer: " .. (m and m.DisplayName or "-"))
			sheriffLabel:Set("Sheriff: " .. (s and s.DisplayName or "-"))
			myRoleLabel:Set("You: " .. (inRound(LP) and roleOf(LP) or "-"))
			if m or s then
				emptySince = nil
			else
				emptySince = emptySince or os.clock()
				if os.clock() - emptySince > 5 then announced = {} end
			end
			if Flags.role_notify then
				if m and announced.m ~= m then
					announced.m = m
					notify(m == LP and "You're the murderer." or (m.DisplayName .. " is the murderer."), "Murderer", 6)
				end
				if s then
					local r = roleOf(s)
					local key = s.Name .. ":" .. r -- a new person, or the same person becoming hero
					if announced.s ~= key then
						announced.s = key
						notify(s == LP and ("You're the " .. r:lower() .. ".") or (s.DisplayName .. " is the " .. r:lower() .. "."), r, 6)
					end
				end
			end
			task.wait(0.5)
		end
	end)

	local function rejoin()
		pcall(function()
			if #Players:GetPlayers() <= 1 then
				TeleportService:Teleport(game.PlaceId, LP)
			else
				TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LP)
			end
		end)
	end

	local function serverHop()
		local ok, body = pcall(function()
			return game:HttpGet(("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Desc&limit=100"):format(game.PlaceId))
		end)
		if not ok then notify("Couldn't get the server list.") return end
		local okJson, data = pcall(function() return HttpService:JSONDecode(body) end)
		local ids = {}
		if okJson and type(data) == "table" and type(data.data) == "table" then
			for _, srv in ipairs(data.data) do
				local playing, max = tonumber(srv.playing), tonumber(srv.maxPlayers)
				if srv.id ~= game.JobId and playing and max and playing < max then table.insert(ids, srv.id) end
			end
		end
		if #ids == 0 then notify("No other servers with space right now.") return end
		notify("Hopping servers...")
		pcall(function() TeleportService:TeleportToPlaceInstance(game.PlaceId, ids[math.random(#ids)], LP) end)
	end

	on(LP.Idled, function()
		if not Flags.anti_afk then return end
		pcall(function()
			local vu = game:GetService("VirtualUser")
			vu:CaptureController()
			vu:ClickButton2(Vector2.new())
		end)
	end)

	local rejoining = false
	on(GuiService.ErrorMessageChanged, function(msg)
		if not Flags.auto_rejoin or rejoining or not msg or msg == "" then return end
		rejoining = true
		notify("Disconnected, rejoining...")
		task.wait(2)
		rejoin()
		rejoining = false
	end)

	local ServerBox = Misc:AddGroup("Server", "Right")
	ServerBox:AddToggle("anti_afk", { Text = "Anti AFK", Default = true, Tooltip = "Stops Roblox kicking you for being idle" })
	ServerBox:AddToggle("auto_rejoin", { Text = "Auto Rejoin On Kick", Tooltip = "Rejoins the same server if you get disconnected" })
	ServerBox:AddButton({ Text = "Rejoin Server", Callback = rejoin })
	ServerBox:AddButton({ Text = "Server Hop", Tooltip = "Joins a different server with space", Callback = serverHop })
	ServerBox:AddButton({ Text = "Copy Server ID", Callback = function()
		if typeof(setclipboard) == "function" then
			setclipboard(game.JobId)
			notify("Server ID copied.")
		else
			notify("Your executor can't copy to the clipboard.")
		end
	end })
end

loader:Step("Initialising autofarm systems...")
------------------------------------------------------------------------
-- Autofarm
------------------------------------------------------------------------
do
	local Autofarm = Window:AddTab("Autofarm")
	local TweenService = game:GetService("TweenService")
	Autofarm:AddMasterToggle("autofarm_enabled", { Text = "Autofarm", Default = true, Tooltip = "Master switch for every autofarm feature" })

	local CoinsBox = Autofarm:AddGroup("Coins", "Left")
	CoinsBox:AddToggle("coin_farm", { Text = "Auto Collect Coins", Tooltip = "Collects every coin for you" })
	CoinsBox:AddToggle("farm_hide", { Text = "Stay Under Map", Default = true, Tooltip = "Lies you flat under the map while farming, so the murderer can't reach you" })
	CoinsBox:AddSlider("glide_speed", { Text = "Glide Speed", Min = 10, Max = 42, Default = 28, Suffix = " studs/s", Tooltip = "How fast you glide between coins. 45 studs/s is the most the server allows, so this stops at 42. 28 is the safe default" })
	CoinsBox:AddToggle("avoid_murderer", { Text = "Avoid Murderer", Default = true, Tooltip = "Skips coins near the murderer when you have to pop up to grab one" })
	CoinsBox:AddSlider("avoid_radius", { Text = "Avoid Radius", Min = 10, Max = 60, Default = 25, Suffix = " studs" })
	CoinsBox:AddToggle("reset_full", { Text = "Reset When Bag Full", Tooltip = "Resets your character once the bag is full" })
	CoinsBox:AddSlider("bag_size", { Text = "Bag Size", Min = 10, Max = 50, Default = 40, Tooltip = "40 normally, 50 with Elite" })
	local coinLabel = CoinsBox:AddLabel("Collected this round: 0")

	local sendReport -- defined below, with the rest of the report code
	local HookBox = Autofarm:AddGroup("Discord Report", "Right")
	HookBox:AddTextbox("hook_url", { Text = "Webhook", Placeholder = "paste your Discord webhook link", Tooltip = "Kept on this computer only. Reports go straight to this link" })
	HookBox:AddToggle("hook_enabled", { Text = "Send Coin Reports", Tooltip = "Posts how many coins you've picked up to your Discord channel" })
	HookBox:AddSlider("hook_interval", { Text = "Report Every", Min = 1, Max = 60, Default = 10, Suffix = " min" })
	HookBox:AddSlider("hook_hours", { Text = "Keep Reporting For", Min = 0, Max = 24, Default = 0, Rounding = 1, Suffix = " h", Tooltip = "0 keeps reporting until you turn it off" })
	HookBox:AddButton({ Text = "Send Test Report", Callback = function()
		task.spawn(function() if sendReport("test") then notify("Sent a test report.", "Report", 3) end end)
	end })

	-- lying on your back keeps the whole body a stud or two tall
	local FLAT = CFrame.Angles(math.rad(90), 0, 0)
	local HIDE_DEPTH = 12 -- studs below the lowest coin: where we wait when there's nothing to take
	-- Jumping straight to each coin (instant moves) got us kicked for an invalid position, so every move
	-- is a smooth glide. The Glide Speed slider sets the pace; its default is one the server accepts.
	local function glideSpeed() return math.min(Flags.glide_speed or 28, 42) end -- studs per second; 45 is the most the server allows
	-- How far below a coin to be when taking it, deepest first. We try the deepest and only come up
	-- (and then stay at that depth) if the server doesn't register the touch from there.
	local TOUCH_DEPTHS = { 5, 2, 0 }
	local depthIdx = 1
	local hasTouch = typeof(firetouchinterest) == "function"

	-- the game's own per-round count when it's in the player data, otherwise our own tally
	local localCount = 0
	local sessionCoins, roundsDone = 0, 0 -- all rounds since the script started (for the Discord report)
	local function gotCoin() localCount += 1; sessionCoins += 1 end
	local function coinsHeld()
		local d = dataOf(LP)
		return (d and tonumber(d.Coins)) or localCount
	end

	local function stillFarming() return running() and Flags.autofarm_enabled and Flags.coin_farm and not busy end

	local skipUntil = setmetatable({}, { __mode = "k" }) -- coin -> when to try it again (the murderer was too close)
	local function murdererNear(pos, radius)
		if roleOf(LP) == "Murderer" then return false end
		local m = findRole("Murderer")
		local r = m and rootOf(m)
		return r ~= nil and (r.Position - pos).Magnitude <= radius
	end

	local function nextCoin(me, avoid)
		local murderer = avoid and roleOf(LP) ~= "Murderer" and findRole("Murderer")
		local mr = murderer and rootOf(murderer)
		local radius = Flags.avoid_radius or 25
		local now = os.clock()
		local best, bestCost
		for _, coin in ipairs(liveCoins()) do
			if (skipUntil[coin] or 0) < now and (not mr or (coin.Position - mr.Position).Magnitude > radius) then
				local d = coin.Position - me.Position
				-- climbing is what shows us to the murderer, so a coin on another storey costs extra
				local cost = math.sqrt(d.X * d.X + d.Z * d.Z) + math.abs(d.Y) * 1.5
				if not bestCost or cost < bestCost then best, bestCost = coin, cost end
			end
		end
		return best
	end

	-- fire the touch both ways, like the engine would
	local function touch(coin)
		local me = myRoot()
		if not (hasTouch and me) then return end
		pcall(firetouchinterest, me, coin, 0)
		pcall(firetouchinterest, me, coin, 1)
	end

	------------------------------------------------------------------
	-- stay under the map
	------------------------------------------------------------------
	local hiding, hideY, homeCF, pin = false, nil, nil, nil
	local displaced = 0

	-- Pickup aura: touch every live coin within reach without moving to it, wait a moment, and see which
	-- ones really went. It learns how far the server allows: the reach grows past the farthest coin it
	-- took, shrinks when nothing is taken, and after a few empty sweeps it gives up for the round and the
	-- farm goes back to climbing under each coin. No setting for it: it just finds what works.
	local reach, sweepFails, sweepDead = 40, 0, false
	local function sweep()
		local me = myRoot()
		if sweepDead or not (hasTouch and me) then return 0 end
		local targets = {}
		for _, coin in ipairs(liveCoins()) do
			local d = (coin.Position - me.Position).Magnitude
			if d <= reach then table.insert(targets, { coin = coin, d = d }) end
		end
		if #targets == 0 then return 0 end
		table.sort(targets, function(a, b) return a.d < b.d end)
		for i = 1, math.min(#targets, 15) do touch(targets[i].coin) end
		local t0 = os.clock()
		while os.clock() - t0 < 0.2 and stillFarming() do RunService.Heartbeat:Wait() end
		local got, farGot = 0, 0
		for i = 1, math.min(#targets, 15) do
			if not isCoinLive(targets[i].coin) then
				got += 1
				gotCoin()
				if targets[i].d > farGot then farGot = targets[i].d end
			end
		end
		if got > 0 then
			sweepFails = 0
			reach = math.clamp(math.max(reach, farGot + 8), 15, 40)
		else
			sweepFails += 1
			reach = reach * 0.7
			if sweepFails >= 3 then
				sweepDead = true
				notify("The server only takes coins up close, so I'll climb to each one instead.", "Autofarm", 6)
			end
		end
		return got
	end


	-- Everything that moves us while hiding just sets `pin`; this puts us there every frame, so
	-- gravity never gets a chance to pull us down into the void (also when there are no coins left).
	on(RunService.Heartbeat, function()
		if not (hiding and pin) then return end
		local c, me = LP.Character, myRoot()
		if c and me then
			c:PivotTo(pin)
			me.AssemblyLinearVelocity = Vector3.zero
		end
	end)

	-- one level under the whole map, so there are no floors, pits or upper decks to worry about:
	-- below the lowest coin (or anyone standing even lower), by HIDE_DEPTH
	local function hideLevel()
		local cc = State.map and State.map:FindFirstChild("CoinContainer", true)
		if not cc then return nil end
		local lowest = math.huge
		for _, c in ipairs(cc:GetChildren()) do
			if c:IsA("BasePart") and c.Position.Y < lowest then lowest = c.Position.Y end
		end
		for _, p in ipairs(Players:GetPlayers()) do
			local r = rootOf(p)
			if r and inRound(p) and r.Position.Y < lowest then lowest = r.Position.Y end
		end
		if lowest == math.huge then return nil end
		-- never below the height where Roblox destroys anything that falls
		return math.max(lowest - HIDE_DEPTH, workspace.FallenPartsDestroyHeight + 25)
	end

	local function descend()
		local me = myRoot()
		local y = me and hideLevel()
		if not y then return false end
		local h = myHum()
		homeCF, hideY = me.CFrame, y
		if h then h.PlatformStand = true end
		forceNoclip = true
		pin = CFrame.new(me.Position) * FLAT -- lie down where we are; the glides carry us under
		hiding = true
		return true
	end

	-- the same spot, standing upright: keeps only which way it faced
	local function uprightAt(pos, facing)
		local _, yaw = facing:ToOrientation()
		return CFrame.new(pos) * CFrame.Angles(0, yaw, 0)
	end

	-- Put the character back on its feet. This settles over a few frames (position, every part's
	-- velocity and the GettingUp state, each frame), because the humanoid can stay lying down after
	-- PlatformStand ends. `settle` is false during unload, which can't wait.
	local function standUp(cf, settle)
		local c, h = LP.Character, myHum()
		if not c then return end
		for _ = 1, settle and 12 or 1 do
			if not (c.Parent and myRoot()) then break end
			c:PivotTo(cf)
			for _, d in ipairs(c:GetDescendants()) do
				if d:IsA("BasePart") then
					d.AssemblyLinearVelocity = Vector3.zero
					d.AssemblyAngularVelocity = Vector3.zero
				end
			end
			if h then
				h.PlatformStand = false
				h.Sit = false
				h:ChangeState(Enum.HumanoidStateType.GettingUp)
			end
			if settle then RunService.Heartbeat:Wait() end
		end
	end

	-- One smooth move. It eases up to speed and back down (never above the server's limit, with a little
	-- natural variation in pace) and is stepped by the real time of each frame, so a slow frame can't turn
	-- into a jump. `keepGoing` ends it early; the pin carries the character each frame.
	local function moveTo(target, speed, keepGoing)
		local me = myRoot()
		if not me then return end
		local v = math.min(speed * (0.94 + math.random() * 0.1), 41)
		local ramp = 0.25
		local pos = pin and pin.Position or me.Position
		local t = 0
		while hiding and keepGoing() do
			local remaining = (target - pos).Magnitude
			if remaining < 0.1 then
				pin = CFrame.new(target) * FLAT
				return
			end
			local dt = math.min(RunService.Heartbeat:Wait(), 0.05)
			t += dt
			local sp = v * math.clamp(math.min(t / ramp, remaining / (v * ramp)), 0.12, 1)
			pos += (target - pos).Unit * math.min(sp * dt, remaining)
			pin = CFrame.new(pos) * FLAT
		end
	end

	local function surface(settle)
		if not hiding then return end
		local me = myRoot()
		-- alive on the map: back to where we were (or a spawn if that's somehow unknown)
		local home = me and State.map and inRound(LP) and (homeCF and uprightAt(homeCF.Position, homeCF) or spawnCFrame(State.map)) or nil
		if settle and home and pin and running() then
			-- glide back instead of jumping there: a jump that long is what trips "invalid position"
			moveTo(home.Position, math.min(Flags.glide_speed or 28, 42), function() return running() and inRound(LP) end)
		end
		hiding, pin = false, nil
		forceNoclip = false
		local h = myHum()
		if h then h.PlatformStand = false end
		local root = myRoot()
		if root then
			-- between rounds the game moves us itself; just get off our back where we are
			standUp(home or uprightAt(root.Position, root.CFrame), settle)
		end
		homeCF = nil
	end

	local function glideTo(target, speed) moveTo(target, speed, stillFarming) end

	local function holdFor(maxTime, done)
		local t0 = os.clock()
		while hiding and stillFarming() and os.clock() - t0 < maxTime and not done() do
			RunService.Heartbeat:Wait()
		end
	end

	-- Travel at the resting depth, under everything, and only climb right under the coin being taken
	-- (never diagonally through a building to the next coin). Coins in reach are taken first without
	-- moving at all. If the murderer is near a coin, leave it for a while. Pauses a moment after each coin.
	-- Returns false if there was nothing to do.
	local function farmStepHidden()
		local me = myRoot()
		if not me then return false end
		if hiding and pin and (me.Position - pin.Position).Magnitude > 20 then
			-- something moved us away from where we're pinned; after a few times give up hiding rather than fight the game
			displaced += 1
			hiding = false
			if displaced >= 3 then
				notify("The game keeps moving you out from under the map. Switching Stay Under Map off.", "Autofarm", 6)
				Options.farm_hide:Set(false)
				return true
			end
		end
		if not hiding and not descend() then return false end

		if sweep() > 0 then return true end

		local coin = nextCoin(me, Flags.avoid_murderer)
		local here = pin.Position
		-- always back down to the resting depth first: from anywhere, the way to the next coin is under the map
		if here.Y > hideY + 1 then glideTo(Vector3.new(here.X, hideY, here.Z), glideSpeed()) end
		if not coin then return false end

		glideTo(Vector3.new(coin.Position.X, hideY, coin.Position.Z), glideSpeed())
		if not (hiding and isCoinLive(coin) and stillFarming()) then return true end
		if murdererNear(coin.Position, math.max(Flags.avoid_radius or 25, 15)) then
			skipUntil[coin] = os.clock() + 6 -- he wandered over while we were travelling
			return true
		end

		-- rise to just under the coin; come up a little more only if the touch doesn't register
		local got = false
		for i = depthIdx, #TOUCH_DEPTHS do
			local y = math.max(coin.Position.Y - TOUCH_DEPTHS[i], hideY)
			glideTo(Vector3.new(coin.Position.X, y, coin.Position.Z), glideSpeed())
			local t0 = os.clock()
			local spooked = false
			while hiding and stillFarming() and isCoinLive(coin) and os.clock() - t0 < 0.3 do
				if pin and murdererNear(pin.Position, 14) then spooked = true break end
				touch(coin)
				RunService.Heartbeat:Wait()
			end
			if not isCoinLive(coin) then
				got = true
				depthIdx = i
				break
			end
			if spooked then
				skipUntil[coin] = os.clock() + 6
				break
			end
		end
		if got then gotCoin() end

		-- straight back down out of sight, then a short breather before the next coin
		if hiding and stillFarming() then
			glideTo(Vector3.new(coin.Position.X, hideY, coin.Position.Z), glideSpeed())
			holdFor(0.18 + math.random() * 0.12, function() return false end)
		end
		return true
	end

	------------------------------------------------------------------
	-- the plain version: glide coin to coin through the map (Stay Under Map off)
	------------------------------------------------------------------
	local function farmStepFloor()
		local me = myRoot()
		if not me then return false end
		forceNoclip = true
		if sweep() > 0 then return true end
		local coin = nextCoin(me, Flags.avoid_murderer)
		if not coin then return false end
		local tw = TweenService:Create(me, TweenInfo.new((coin.Position - me.Position).Magnitude / glideSpeed(), Enum.EasingStyle.Linear),
			{ CFrame = CFrame.new(coin.Position) * me.CFrame.Rotation })
		tw:Play()
		while tw.PlaybackState == Enum.PlaybackState.Playing do
			if not (stillFarming() and isCoinLive(coin) and me.Parent) then tw:Cancel() break end
			me.AssemblyLinearVelocity = Vector3.zero
			task.wait()
		end
		if isCoinLive(coin) and me.Parent and stillFarming() then
			touch(coin)
			-- hold still on the coin (noclip is on, so we'd otherwise sink through the floor)
			local t0 = os.clock()
			while isCoinLive(coin) and me.Parent and os.clock() - t0 < 0.5 do
				me.CFrame = CFrame.new(coin.Position) * me.CFrame.Rotation
				me.AssemblyLinearVelocity = Vector3.zero
				task.wait()
			end
			if not isCoinLive(coin) then gotCoin() end
		end
		task.wait(0.18 + math.random() * 0.12) -- a short breather before the next coin
		return true
	end

	-- Once the round's coins are all taken (or the bag is full) there's nothing left to farm. Rise a few
	-- studs right where we are (no jump back to where we started), stand up, then climb to the safe spot,
	-- the same platform as the Safe Spot key. It's put away again when the round ends.
	local parked = false
	local function parkAtSafeSpot(why)
		parked = true
		local me = myRoot()
		if hiding and me and pin then
			local up = pin.Position + Vector3.new(0, 8, 0)
			moveTo(up, glideSpeed(), running)
			hiding, pin = false, nil
			forceNoclip = false
			local h = myHum()
			if h then h.PlatformStand = false end
			local root = myRoot()
			if root then standUp(uprightAt(up, root.CFrame), true) end
			homeCF = nil
		end
		forceNoclip = false
		if not Flags.safe_spot and myRoot() then
			State.smoothSafe = true
			Options.safe_spot:Set(true)
			notify(why .. " Climbing to the safe spot.", "Autofarm", 4)
		end
	end

	------------------------------------------------------------------
	-- Discord reports: one embed per report, to the webhook you paste in
	------------------------------------------------------------------
	local httpRequest = (typeof(request) == "function" and request)
		or (typeof(http_request) == "function" and http_request)
		or (typeof(syn) == "table" and typeof(syn.request) == "function" and syn.request)
		or (typeof(http) == "table" and typeof(http.request) == "function" and http.request)
		or (typeof(fluxus) == "table" and typeof(fluxus.request) == "function" and fluxus.request)
		or nil

	-- the "special letters" Discord shows in embeds: sans-serif bold and small caps
	local function bold(str)
		return (str:gsub("[%a%d]", function(c)
			local b = c:byte()
			if b >= 65 and b <= 90 then return utf8.char(0x1D5D4 + b - 65) end
			if b >= 97 and b <= 122 then return utf8.char(0x1D5EE + b - 97) end
			return utf8.char(0x1D7EC + b - 48)
		end))
	end
	local SMALL = { a = "ᴀ", b = "ʙ", c = "ᴄ", d = "ᴅ", e = "ᴇ", f = "ꜰ", g = "ɢ", h = "ʜ", i = "ɪ", j = "ᴊ", k = "ᴋ", l = "ʟ", m = "ᴍ",
		n = "ɴ", o = "ᴏ", p = "ᴘ", q = "ǫ", r = "ʀ", s = "ꜱ", t = "ᴛ", u = "ᴜ", v = "ᴠ", w = "ᴡ", x = "x", y = "ʏ", z = "ᴢ" }
	local function small(str) return (str:lower():gsub("%a", SMALL)) end

	local function fmtNum(n)
		local text = tostring(math.floor(n + 0.5))
		text = text:reverse():gsub("(%d%d%d)", "%1,"):reverse()
		return (text:gsub("^,", ""))
	end
	local function fmtTime(sec)
		sec = math.floor(sec)
		local h, m, r = math.floor(sec / 3600), math.floor(sec % 3600 / 60), sec % 60
		if h > 0 then return string.format("%dh %02dm", h, m) end
		if m > 0 then return string.format("%dm %02ds", m, r) end
		return r .. "s"
	end
	local function meter(frac, cells)
		local filled = math.clamp(math.floor(frac * cells + 0.5), 0, cells)
		return string.rep("▰", filled) .. string.rep("▱", cells - filled)
	end
	local function validHook(url)
		if type(url) ~= "string" then return false end
		return url:match("^https://[%w%.]*discord%.com/api/webhooks/%d+/[%w%-_]+") ~= nil
			or url:match("^https://[%w%.]*discordapp%.com/api/webhooks/%d+/[%w%-_]+") ~= nil
	end

	local reportStart, baseCoins, baseRounds -- when reporting began, and the totals at that moment

	local function buildReport(kind)
		local name = (LP.DisplayName ~= "" and LP.DisplayName) or LP.Name
		local since = reportStart and (os.clock() - reportStart) or 0
		local total = sessionCoins - (baseCoins or 0)
		local rate = since >= 60 and (total / since * 3600) or nil
		local bag = Flags.bag_size or 40
		local held = coinsHeld()
		local frac = math.clamp(held / math.max(bag, 1), 0, 1)
		local status
		if parked then status = "+ Parked at the safe spot"
		elseif stillFarming() and inRound(LP) then status = "+ Farming"
		elseif inRound(LP) then status = "- Autofarm is off"
		else status = "- Waiting for a round" end

		local title = "🪙  " .. bold("COIN REPORT")
		if kind == "test" then title = title .. "  ·  " .. bold("TEST") end
		if kind == "final" then title = "🏁  " .. bold("FINAL REPORT") end
		local footer = small("xpware v" .. VERSION)
		if kind == "report" then footer = footer .. "  •  " .. small("next report in " .. (Flags.hook_interval or 10) .. " min") end

		return {
			username = "xpware",
			embeds = { {
				author = { name = bold("xpware") .. "  •  " .. bold("Autofarm") },
				title = title,
				description = table.concat({
					"> ✦ " .. small("live farm report") .. " ✦",
					"> " .. small("murder mystery 2") .. "  ·  **" .. name .. "**",
					"-# " .. small("sent by xpware"),
				}, "\n"),
				color = 0x316AC5,
				fields = {
					{ name = "🪙  " .. bold("This Round"), value = "```fix\n" .. held .. " / " .. bag .. " coins\n```" .. meter(frac, 10) .. " **" .. math.floor(frac * 100) .. "%**", inline = true },
					{ name = "💰  " .. bold("Collected"), value = "```yaml\n" .. fmtNum(total) .. " coins\n```", inline = true },
					{ name = "⚡  " .. bold("Pace"), value = "```ini\n[ " .. (rate and fmtNum(rate) or "--") .. " / hr ]\n```", inline = true },
					{ name = "🏁  " .. bold("Rounds"), value = "```css\n" .. (roundsDone - (baseRounds or 0)) .. " farmed\n```", inline = true },
					{ name = "⏱️  " .. bold("Uptime"), value = "```fix\n" .. fmtTime(since) .. "\n```", inline = true },
					{ name = "📡  " .. bold("Status"), value = "```diff\n" .. status .. "\n```", inline = true },
				},
				footer = { text = footer },
				timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
			} },
		}
	end

	-- kind: "report" (the regular one), "test" or "final". Returns true if Discord took it.
	function sendReport(kind)
		local url = Flags.hook_url
		if not validHook(url) then notify("Paste a Discord webhook link first (discord.com/api/webhooks/...).", "Report", 5) return false end
		if not httpRequest then notify("Your executor can't send web requests.", "Report", 5) return false end
		local ok, res = pcall(httpRequest, {
			Url = url, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
			Body = HttpService:JSONEncode(buildReport(kind)),
		})
		local code = ok and type(res) == "table" and (res.StatusCode or res.status_code) or nil
		if code and code >= 200 and code < 300 then return true end
		notify("Discord didn't accept the report" .. (code and (" (" .. code .. ")") or "") .. ". Check the webhook link.", "Report", 5)
		return false
	end

	task.spawn(function()
		local lastSent
		while running() do
			if Flags.hook_enabled then
				if not reportStart then
					reportStart, baseCoins, baseRounds, lastSent = os.clock(), sessionCoins, roundsDone, -math.huge
				end
				local now = os.clock()
				local hours = Flags.hook_hours or 0
				if hours > 0 and now >= reportStart + hours * 3600 then
					sendReport("final")
					notify("Reported for " .. hours .. " h as asked, so reports are off now.", "Report", 5)
					Options.hook_enabled:Set(false)
				elseif now - lastSent >= (Flags.hook_interval or 10) * 60 then
					lastSent = now
					task.spawn(sendReport, "report")
				end
			else
				reportStart = nil
			end
			task.wait(1)
		end
	end)

	task.spawn(function()
		while running() do
			local active = stillFarming() and inRound(LP)
			if hiding and not (active and Flags.farm_hide) then surface(true) end
			if active and not parked then
				local ok, moved = pcall(Flags.farm_hide and farmStepHidden or farmStepFloor)
				if not ok then warn("[xpware] coin farm: " .. tostring(moved)) end
				if not (ok and moved) then
					if not hiding then forceNoclip = false end
					if ok and localCount > 0 and #liveCoins() == 0 then
						parkAtSafeSpot("Every coin is collected.")
					else
						task.wait(0.3) -- nothing to collect right now; if hiding, the pin keeps us safe meanwhile
					end
				end
				if not parked and not Flags.reset_full and coinsHeld() >= (Flags.bag_size or 40) then
					parkAtSafeSpot("The bag is full.")
				end
				if Flags.reset_full and coinsHeld() >= (Flags.bag_size or 40) then
					local h = myHum()
					if h and h.Health > 0 then
						h.Health = 0
						notify("Bag full, resetting.", "Autofarm", 3)
					end
				end
			else
				if not hiding then forceNoclip = false end
				if not inRound(LP) then
					if localCount > 0 then roundsDone += 1 end
					localCount, displaced, depthIdx = 0, 0, 1
					reach, sweepFails, sweepDead = 40, 0, false
					if parked then
						-- the round is over: put the platform away without teleporting back to the old map spot
						parked = false
						if Flags.safe_spot then
							safeReturn = nil
							Options.safe_spot:Set(false)
						end
					end
				end
				task.wait(0.3)
			end
			coinLabel:Set("Collected this round: " .. coinsHeld())
		end
	end)

	-- a new character is a fresh start: nothing to pin or put back
	on(LP.CharacterAdded, function()
		hiding, pin, homeCF = false, nil, nil
		forceNoclip = false
	end)
	onUnload(surface)
end

loader:Step("Scanning the emote library...")
------------------------------------------------------------------------
-- Fun
------------------------------------------------------------------------
do
	local Fun = Window:AddTab("Fun")

	-- MM2's own emotes. The game plays one by firing the local event Remotes.Misc.PlayEmote with
	-- the emote's key ("zen", "sit", "ninja", ...); its animation script then plays the animation
	-- on your character, and Roblox replicates that to everyone. The full list comes from the
	-- game's database (Database.Sync.Emotes), not just the emotes you own. Toys are left out.
	local gameRemotes = ReplicatedStorage:FindFirstChild("Remotes")
	local gameMisc = gameRemotes and gameRemotes:FindFirstChild("Misc")
	local PlayEmote = gameMisc and gameMisc:FindFirstChild("PlayEmote")

	local emoteByLabel, emoteNames = {}, {}

	local function loadEmotes()
		local ok, sync = pcall(function() return require(ReplicatedStorage.Database.Sync) end)
		if not (ok and type(sync) == "table") then
			ok, sync = pcall(function() return { Emotes = require(ReplicatedStorage.Database.Sync.Emotes) } end)
		end
		if not (ok and type(sync) == "table") then return end

		local custom, basic = {}, {}
		if type(sync.Emotes) == "table" then
			for key, info in pairs(sync.Emotes) do
				-- "Back" is the menu's back button, not an emote
				if type(key) == "string" and key ~= "Back" and type(info) == "table" then
					table.insert(info.AnimationID and custom or basic,
						{ key = key, info = info, name = tostring(info.Name or key) })
				end
			end
		end
		-- the game's custom animations first, then the Roblox basics
		for _, group in ipairs({ custom, basic }) do
			table.sort(group, function(a, b) return a.name:lower() < b.name:lower() end)
			for _, e in ipairs(group) do
				local label = e.name
				if emoteByLabel[label] then label = label .. " [" .. e.key .. "]" end
				emoteByLabel[label] = e
				table.insert(emoteNames, label)
			end
		end
	end
	loadEmotes()
	if #emoteNames == 0 then -- no database to read: the Roblox basics still work through the same event
		for _, key in ipairs({ "wave", "cheer", "laugh", "point", "dance1", "dance2", "dance3" }) do
			emoteByLabel[key] = { key = key, info = {}, name = key }
			table.insert(emoteNames, key)
		end
	end

	-- matches the label, or the key, ignoring case (older saved settings hold names like "Dance")
	local function findEmote(label)
		if type(label) ~= "string" then return nil end
		if emoteByLabel[label] then return emoteByLabel[label] end
		local l = label:lower()
		for name, e in pairs(emoteByLabel) do
			if name:lower() == l or e.key:lower() == l then return e end
		end
		return nil
	end

	-- Emote tracks that are playing, the game's or our own fallback. The game names its emote
	-- track after the emote ("ninja"); its idle/walk/jump tracks end in "Anim" or are "Animation1".
	local tracks, ownTrack = {}, nil
	local lastFiredAt = 0

	local function isDefaultTrack(name)
		return name:match("Anim$") ~= nil or name:match("^Animation%d*$") ~= nil
	end

	local function hookAnimator(char)
		local h = char:WaitForChild("Humanoid", 5)
		local animator = h and (h:FindFirstChildOfClass("Animator") or h:WaitForChild("Animator", 5))
		if not animator then return end
		on(animator.AnimationPlayed, function(track)
			if os.clock() - lastFiredAt < 1.5 and not isDefaultTrack(track.Name) then tracks[track] = true end
		end)
	end
	if LP.Character then task.spawn(hookAnimator, LP.Character) end

	local function emoteActive()
		local active = false
		for t in pairs(tracks) do
			local ok, playing = pcall(function() return t.IsPlaying end)
			if ok and playing then active = true else tracks[t] = nil end
		end
		return active
	end

	-- returns true if there was something to stop
	local function stopEmote()
		local stopped = false
		for t in pairs(tracks) do
			pcall(function() t:Stop(0.2) end)
			tracks[t] = nil
			stopped = true
		end
		ownTrack = nil
		return stopped
	end
	onUnload(stopEmote)

	-- our own copy of an emote animation, for when the game's script doesn't play it. Action
	-- priority so it wins over the idle/walk tracks; it replicates like any animation we play.
	local function playOwn(entry)
		local id, h = entry.info.AnimationID, myHum()
		if not (id and h) then return false end
		local anim = Instance.new("Animation")
		anim.Name = entry.key
		anim.AnimationId = "rbxassetid://" .. tostring(id)
		local ok, track = pcall(function()
			return (h:FindFirstChildOfClass("Animator") or h):LoadAnimation(anim)
		end)
		if not (ok and track) then return false end
		track.Priority = Enum.AnimationPriority.Action
		track.Looped = entry.info.Loop == true
		track:Play(0.2)
		ownTrack = track
		tracks[track] = true
		return true
	end

	local function playEmote(label)
		local entry = findEmote(label)
		if not entry then notify("Pick an emote first.") return end
		if not PlayEmote then notify("This game has no emote system.") return end
		if not (myHum() and myRoot()) then return end
		stopEmote()
		lastFiredAt = os.clock()
		local my = lastFiredAt
		PlayEmote:Fire(entry.key)
		-- the game's script plays it the instant it's fired; if nothing has started 0.3s later (it
		-- may only play emotes you own, or its idle animation cut in), play the animation ourselves
		task.delay(0.3, function()
			if my == lastFiredAt and not emoteActive() and not entry.toy then playOwn(entry) end
		end)
	end

	-- Emote When Still: starts the moment you stop (checked every frame; the optional wait is 0 by
	-- default), once each time you stop, and again if the emote ends by itself while you stand there. Anything that isn't plain standing (moving, in the air, seated, pinned by
	-- the coin farm, mid-fling) counts as not still and starts the wait over.
	task.spawn(function()
		local stillSince, playedThisStop, sawTrack = nil, false, false
		while running() do
			local h, r = myHum(), myRoot()
			local still = h ~= nil and r ~= nil and h.Health > 0
				and h.MoveDirection.Magnitude < 0.05
				and Vector3.new(r.AssemblyLinearVelocity.X, 0, r.AssemblyLinearVelocity.Z).Magnitude < 0.5
				and h.FloorMaterial ~= Enum.Material.Air
				and not h.PlatformStand and not h.Sit and not busy
			if Flags.auto_emote and still then
				local now = os.clock()
				stillSince = stillSince or now
				local active = emoteActive()
				if active then sawTrack = true end
				if now - stillSince >= (Flags.emote_wait or 0) and not active then
					if not playedThisStop or (sawTrack and now - lastFiredAt > 2) then
						playedThisStop, sawTrack = true, false
						playEmote(Flags.emote)
					end
				end
			else
				stillSince, playedThisStop, sawTrack = nil, false, false
			end
			RunService.Heartbeat:Wait()
		end
	end)

	local spinning, frozen = false, false
	on(RunService.Heartbeat, function(dt)
		local r, h = myRoot(), myHum()
		if not (r and h) then return end
		if Flags.spin and not busy then
			spinning = true
			h.AutoRotate = false
			r.CFrame *= CFrame.Angles(0, (Flags.spin_speed or 10) * 2 * dt, 0)
		elseif spinning then
			spinning = false
			h.AutoRotate = true
		end
		-- Jump spam: grounded, and not seated, pinned or mid-fling. Setting Humanoid.Jump alone is
		-- easily ignored or blocked, so ask for the jump both ways (the flag and the state change),
		-- and switch jumping back on if the game turned it off or set the power to 0.
		if Flags.jump_spam and not busy and not h.Sit and not h.PlatformStand and h.FloorMaterial ~= Enum.Material.Air then
			if not h:GetStateEnabled(Enum.HumanoidStateType.Jumping) then
				h:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
			end
			if h.UseJumpPower then
				if h.JumpPower < 1 then h.JumpPower = 50 end
			elseif h.JumpHeight < 1 then
				h.JumpHeight = 7.2
			end
			h.Jump = true
			h:ChangeState(Enum.HumanoidStateType.Jumping)
		end
		if Flags.freeze then
			if not r.Anchored then r.Anchored = true end
			frozen = true
		elseif frozen then
			r.Anchored = false
			frozen = false
		end
		-- the game's emotes stop by themselves when you move; our fallback copy needs telling
		if ownTrack and (h.MoveDirection.Magnitude > 0.1 or h.Jump) then stopEmote() end
	end)
	on(LP.CharacterAdded, function(char)
		spinning, frozen, tracks, ownTrack = false, false, {}, nil
		task.spawn(hookAnimator, char)
	end)
	onUnload(function()
		local r, h = myRoot(), myHum()
		if r and frozen then r.Anchored = false end
		if h and spinning then h.AutoRotate = true end
	end)

	local CharacterBox = Fun:AddGroup("Character", "Left")
	CharacterBox:AddToggle("spin", { Text = "Spin" })
	CharacterBox:AddSlider("spin_speed", { Text = "Spin Speed", Min = 1, Max = 50, Default = 10 })
	CharacterBox:AddToggle("jump_spam", { Text = "Jump Spam" })
	CharacterBox:AddToggle("freeze", { Text = "Freeze In Place", Tooltip = "Pins you where you stand" })
	CharacterBox:AddButton({ Text = "Sit", Callback = function()
		local h = myHum(); if h then h.Sit = true end
	end })

	local EmotesBox = Fun:AddGroup("Emotes", "Right")
	EmotesBox:AddDropdown("emote", { Text = "Emote", Values = emoteNames,
		Default = emoteByLabel["Zen"] and "Zen" or emoteNames[1] })
	EmotesBox:AddButton({ Text = "Play Emote", Callback = function() playEmote(Flags.emote) end })
	EmotesBox:AddButton({ Text = "Stop Emote", Callback = function()
		if not stopEmote() then notify("Walk or jump to stop an emote.", nil, 2) end
	end })
	EmotesBox:AddToggle("auto_emote", { Text = "Emote When Still", Tooltip = "Plays the selected emote every time you stop moving" })
	EmotesBox:AddSlider("emote_wait", { Text = "Still For", Min = 0, Max = 10, Default = 0, Rounding = 1, Suffix = " s",
		Tooltip = "How long you stand still before the emote starts. 0 = the moment you stop" })
	EmotesBox:AddLabel("These are the game's own emotes, so everyone sees them. Walking cancels them.", { Color = Library.Theme.TextDim })
end

loader:Step("Reading the item database...")
------------------------------------------------------------------------
-- Inventory (local only)
--
-- The game keeps what you own in the ProfileData module (a map of item -> amount for weapons and
-- pets, a list of keys for everything else) and refreshes its screens when the local event
-- Remotes.Inventory.InventoryDataChanged fires with (category, item, amount). Those are the two
-- steps its own code takes when the server sends a new item, so that's all this does. Nothing is
-- sent to the server: nobody else sees any of it, and trades use your real inventory. Equipping a
-- knife or gun also welds its model onto the one you hold, or onto a local copy in your backpack when
-- you have none (see "In-hand skins").
------------------------------------------------------------------------
do
	local InventoryTab = Window:AddTab("Inventory")

	local gameModules = ReplicatedStorage:FindFirstChild("Modules")
	local profileModule = gameModules and gameModules:FindFirstChild("ProfileData")
	local gameRemotes = ReplicatedStorage:FindFirstChild("Remotes")
	local invRemotes = gameRemotes and gameRemotes:FindFirstChild("Inventory")
	local changedEvent = invRemotes and invRemotes:FindFirstChild("InventoryDataChanged")
	local clientServices = ReplicatedStorage:FindFirstChild("ClientServices")
	local equipModule = clientServices and clientServices:FindFirstChild("EquipService")
	local updateClient = ReplicatedStorage:FindFirstChild("UpdateDataClient")

	local CATEGORIES = { "Knives", "Guns", "Effects", "Perks", "Emotes", "Pets", "Radios" }
	local DATA_CATEGORY = { Knives = "Weapons", Guns = "Weapons", Effects = "Effects", Perks = "Perks",
		Emotes = "Emotes", Pets = "Pets", Radios = "Radios" }
	local KEYED = { Weapons = true, Pets = true } -- owned as item -> amount; the rest are lists of keys
	local RARITY_ORDER = { Unique = 1, Ancient = 2, Godly = 3, Legendary = 4, Rare = 5, Uncommon = 6, Common = 7 }

	-- everything in the game's item database, grouped by the categories above ---------------------
	local catalog = {}
	for _, name in ipairs(CATEGORIES) do catalog[name] = {} end

	local function buildCatalog()
		local ok, sync = pcall(function() return require(ReplicatedStorage.Database.Sync) end)
		if not (ok and type(sync) == "table") then return false end
		for _, category in ipairs(CATEGORIES) do
			local dataCategory = DATA_CATEGORY[category]
			local source = sync[dataCategory]
			if type(source) ~= "table" and dataCategory == "Weapons" then source = sync.Item end
			if type(source) == "table" then
				local list = catalog[category]
				for key, info in pairs(source) do
					if type(key) == "string" and type(info) == "table" then
						local keep = true
						if dataCategory == "Weapons" then
							keep = (category == "Knives" and info.ItemType == "Knife") or (category == "Guns" and info.ItemType == "Gun")
						elseif dataCategory == "Emotes" then
							keep = key ~= "Back" and info.AnimationID ~= nil -- no menu button, no Roblox basics
						end
						if keep then
							local name = tostring(info.ItemName or info.Name or info.DisplayName or key)
							local rarity = tostring(info.Rarity or "Common")
							table.insert(list, { key = key, info = info, dataCat = dataCategory, name = name,
								rarity = rarity, label = name .. " (" .. rarity .. ")" })
						end
					end
				end
				-- rarest first, then by name; a duplicate label gets its key added so it stays pickable
				table.sort(list, function(a, b)
					local ra, rb = RARITY_ORDER[a.rarity] or 99, RARITY_ORDER[b.rarity] or 99
					if ra ~= rb then return ra < rb end
					return a.name:lower() < b.name:lower()
				end)
				local seen = {}
				for _, e in ipairs(list) do
					if seen[e.label] then e.label = e.label .. " [" .. e.key .. "]" end
					seen[e.label] = true
				end
			end
		end
		return true
	end
	local catalogOk = buildCatalog()

	-- the game's own data, and what we've changed in it ------------------------------------------
	local profileCache
	local function getProfile()
		if profileCache then return profileCache end
		if not profileModule then return nil end
		local ok, res = pcall(require, profileModule)
		if ok and type(res) == "table" then profileCache = res end
		return profileCache
	end

	local added = {}             -- the entries we put in your inventory
	local originalEquipped = {}  -- itemType -> what you really had equipped, before our local equips

	local function owns(profile, entry)
		local pd = profile[entry.dataCat]
		if type(pd) ~= "table" or type(pd.Owned) ~= "table" then return nil end
		if KEYED[entry.dataCat] then return pd.Owned[entry.key] ~= nil end
		return table.find(pd.Owned, entry.key) ~= nil
	end

	-- returns true if it was added, false if you already have it (or there's nowhere to put it)
	local function addItem(profile, entry)
		local have = owns(profile, entry)
		if have ~= false then return false end
		local pd = profile[entry.dataCat]
		if KEYED[entry.dataCat] then
			pd.Owned[entry.key] = 1
		else
			table.insert(pd.Owned, entry.key)
		end
		table.insert(added, entry)
		if changedEvent then changedEvent:Fire(entry.dataCat, entry.key, 1) end
		return true
	end

	local function refreshGame(profile)
		if updateClient then updateClient:Fire(false, profile) end
	end

	-- puts back your real equipped weapons, locally
	local function restoreEquipped(profile)
		local ok, equip = pcall(require, equipModule)
		for itemType, original in pairs(originalEquipped) do
			if profile.Weapons and profile.Weapons.Equipped then profile.Weapons.Equipped[itemType] = original end
			if ok and type(equip) == "table" and equip.EquippedChanged then equip.EquippedChanged:Fire(itemType, original) end
			originalEquipped[itemType] = nil
		end
	end

	-- In-hand skins ----------------------------------------------------------------------------
	-- The knife or gun you hold is built by the server, so its look can't be changed at the source. But
	-- every item in the database has an ItemID, the model the server builds its weapon from. We load
	-- that model ourselves (game:GetObjects) and weld copies of its parts onto your real weapon's
	-- handle, hiding the real handle. Parts we create never replicate, so only you see any of it.
	local SKIN = "xpware_skin"
	local skinChoice = {} -- "Knife" / "Gun" -> the item chosen
	local modelCache = {} -- ItemID -> the loaded model, so each skin is fetched once
	local skinned = {}    -- tools wearing a skin right now
	local modelFail = {}  -- ItemID -> why its model couldn't load, so we don't retry every half second
	local FAKE = "xpware_fake" -- marks a local stand-in weapon we made for you (value: "Knife" / "Gun")

	local function weaponType(tool)
		if not tool:IsA("Tool") then return nil end
		local fake = tool:GetAttribute(FAKE)
		if fake then return fake end
		if tool:HasTag("Weapon_Knife") or tool.Name == "Knife" then return "Knife" end
		if tool:HasTag("Weapon_Gun") or tool.Name == "Gun" then return "Gun" end
		return nil
	end

	local function clearSkin(tool)
		local holder = tool:FindFirstChild(SKIN)
		if holder then holder:Destroy() end
		local handle = tool:FindFirstChild("Handle")
		local was = tool:GetAttribute("xpware_handle_transparency")
		if handle and was ~= nil then handle.Transparency = was end
		tool:SetAttribute("xpware_handle_transparency", nil)
		tool:SetAttribute(SKIN, nil)
		skinned[tool] = nil
	end

	-- loads an item's model once; returns it, or nil and why not
	local function loadSkin(entry)
		local id = entry.info.ItemID
		if not id then return nil, "that item has no model" end
		if modelCache[id] then return modelCache[id] end
		if modelFail[id] then return nil, modelFail[id] end
		local ok, objects = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(id)) end)
		local root = ok and type(objects) == "table" and objects[1]
		if not root then
			modelFail[id] = "its model couldn't be loaded (it may be private, or your executor can't load models)"
			return nil, modelFail[id]
		end
		local tool = root:IsA("Tool") and root or root:FindFirstChildWhichIsA("Tool", true)
		local container = tool or root
		local handle = container:FindFirstChild("Handle") or container:FindFirstChild("Handle", true)
		if not (handle and handle:IsA("BasePart")) then
			root:Destroy()
			modelFail[id] = "its model has no handle"
			return nil, modelFail[id]
		end
		local parts = {}
		for _, d in ipairs(container:GetDescendants()) do
			if d:IsA("BasePart") then table.insert(parts, d) end
		end
		local skin = { root = root, handle = handle, parts = parts, grip = tool and tool.Grip or CFrame.new() }
		modelCache[id] = skin
		return skin
	end

	-- Copies every part of the skin onto the real handle with explicit Weld offsets (so it doesn't matter
	-- where the tool is when this runs), then hides the real handle. The offset accounts for the two
	-- tools' different grips: the hand holds a tool so that Handle = Hand * Grip^-1.
	local function applySkin(tool, entry)
		if tool:GetAttribute(SKIN) == entry.key then return true end
		clearSkin(tool)
		local handle = tool:FindFirstChild("Handle") or tool:WaitForChild("Handle", 5)
		if not (handle and handle:IsA("BasePart")) then return false, "the weapon has no handle yet" end
		local skin, why = loadSkin(entry)
		if not skin then return false, why end
		if tool:GetAttribute(FAKE) then
			tool.Grip = skin.grip -- so the skin sits in the hand exactly as its own model does
			tool.Name = (entry.name == "Knife" or entry.name == "Gun") and (entry.name .. " ") or entry.name
		end

		local holder = Instance.new("Model")
		holder.Name = SKIN
		local toSkinHandle = tool.Grip * skin.grip:Inverse()
		for _, part in ipairs(skin.parts) do
			local copy = part:Clone()
			for _, d in ipairs(copy:GetDescendants()) do
				if d:IsA("LuaSourceContainer") or d:IsA("JointInstance") or d:IsA("WeldConstraint")
					or d:IsA("TouchTransmitter") or d:IsA("Sound") then
					d:Destroy()
				end
			end
			copy.Anchored = false
			copy.CanCollide, copy.CanTouch, copy.CanQuery, copy.Massless = false, false, false, true
			local weld = Instance.new("Weld")
			weld.Part0, weld.Part1 = handle, copy
			weld.C0 = toSkinHandle * skin.handle.CFrame:ToObjectSpace(part.CFrame)
			weld.Parent = copy
			copy.Parent = holder
		end
		if tool:GetAttribute("xpware_handle_transparency") == nil then
			tool:SetAttribute("xpware_handle_transparency", handle.Transparency)
		end
		handle.Transparency = 1
		holder.Parent = tool
		tool:SetAttribute(SKIN, entry.key)
		skinned[tool] = true
		return true
	end

	local function weaponTools()
		local list = {}
		for _, holder in ipairs({ LP.Character, LP:FindFirstChildOfClass("Backpack") }) do
			if holder then
				for _, t in ipairs(holder:GetChildren()) do
					local kind = weaponType(t)
					if kind then table.insert(list, { tool = t, kind = kind }) end
				end
			end
		end
		return list
	end

	-- Outside a round you have no knife or gun, so there'd be nothing to dress. Then we put a local stand-in
	-- in your backpack: tagged like the real thing so the game's own Knife / Gun buttons equip it, but
	-- named differently so this script's role checks don't mistake it for the real weapon. The moment the
	-- server gives you the real one, the stand-in goes.
	local function syncFakes()
		for kind, entry in pairs(skinChoice) do
			local real, fakes = false, {}
			for _, w in ipairs(weaponTools()) do
				if w.kind == kind then
					if w.tool:GetAttribute(FAKE) then table.insert(fakes, w.tool) else real = true end
				end
			end
			if real then
				for _, t in ipairs(fakes) do skinned[t] = nil t:Destroy() end
			elseif #fakes == 0 then
				local backpack = LP:FindFirstChildOfClass("Backpack")
				local skin = backpack and loadSkin(entry)
				if skin then
					local tool = Instance.new("Tool")
					tool.Name = entry.name
					tool.CanBeDropped = false
					tool.RequiresHandle = true
					tool:SetAttribute(FAKE, kind)
					pcall(function() tool:AddTag("Weapon_" .. kind) end)
					local handle = Instance.new("Part")
					handle.Name = "Handle"
					handle.Size = Vector3.new(1, 1, 1)
					handle.Transparency = 1
					handle.CanCollide, handle.CanTouch, handle.CanQuery, handle.Massless = false, false, false, true
					handle.Parent = tool
					tool.Parent = backpack
				end
			end
		end
	end

	-- puts the chosen skin on every knife / gun you have, and takes it off any you've unchosen
	local applying, pending = false, false
	local function applySkins(report)
		if applying then pending = true return end
		applying = true
		local problem
		syncFakes()
		for _, entry in pairs(skinChoice) do
			local id = entry.info.ItemID
			if not id then problem = "that item has no model" elseif modelFail[id] then problem = modelFail[id] end
		end
		for _, w in ipairs(weaponTools()) do
			local entry = skinChoice[w.kind]
			if entry then
				local ok, why = applySkin(w.tool, entry)
				if not ok then problem = why end
			elseif skinned[w.tool] then
				clearSkin(w.tool)
			end
		end
		applying = false
		if report and problem then notify("Couldn't show that skin: " .. problem .. ".", "Inventory", 6) end
		if pending then
			pending = false
			task.defer(applySkins)
		end
	end

	local function clearAllSkins()
		skinChoice = {}
		for _, w in ipairs(weaponTools()) do
			if w.tool:GetAttribute(FAKE) then skinned[w.tool] = nil w.tool:Destroy() else clearSkin(w.tool) end
		end
		for tool in pairs(skinned) do clearSkin(tool) end
	end

	-- the server builds a fresh knife and gun every round: dress them as they arrive
	local function onWeaponAdded(inst)
		local kind = weaponType(inst)
		if kind and skinChoice[kind] then task.spawn(applySkins) end
	end
	on(LP.DescendantAdded, onWeaponAdded) -- the Backpack's contents
	local function hookCharacter(char)
		on(char.ChildAdded, onWeaponAdded)
		task.delay(1.5, function() if running() and next(skinChoice) then applySkins() end end)
	end
	if LP.Character then hookCharacter(LP.Character) end
	on(LP.CharacterAdded, hookCharacter)

	-- the server's own scripts may show the real handle again; keep it hidden
	task.spawn(function()
		while running() do
			if next(skinChoice) then applySkins() end
			for tool in pairs(skinned) do
				if not tool.Parent then
					skinned[tool] = nil
				else
					local handle = tool:FindFirstChild("Handle")
					if handle and handle.Transparency ~= 1 then handle.Transparency = 1 end
				end
			end
			task.wait(0.5)
		end
	end)

	local function removeAdded()
		local profile = getProfile()
		if not profile then return 0 end
		restoreEquipped(profile)
		clearAllSkins()
		local n = #added
		for i = #added, 1, -1 do
			local e = added[i]
			local pd = profile[e.dataCat]
			if type(pd) == "table" and type(pd.Owned) == "table" then
				if KEYED[e.dataCat] then
					pd.Owned[e.key] = nil
				else
					local at = table.find(pd.Owned, e.key)
					if at then table.remove(pd.Owned, at) end
				end
			end
			if changedEvent then changedEvent:Fire(e.dataCat, e.key, 0) end
			added[i] = nil
		end
		if n > 0 then refreshGame(profile) end
		return n
	end
	onUnload(function()
		pcall(removeAdded)
		pcall(clearAllSkins)
		for _, skin in pairs(modelCache) do pcall(function() skin.root:Destroy() end) end
	end)

	-- the tab ----------------------------------------------------------------------------------
	local shown, byLabel = {}, {}
	local itemDropdown, countLabel
	local working = false

	local function refreshList()
		local category = Flags.inv_category or "Knives"
		local query = (Flags.inv_search or ""):lower()
		shown, byLabel = {}, {}
		local values = {}
		for _, e in ipairs(catalog[category] or {}) do
			if query == "" or e.label:lower():find(query, 1, true) then
				table.insert(shown, e)
				byLabel[e.label] = e
				table.insert(values, e.label)
			end
		end
		itemDropdown:SetValues(values)
		itemDropdown:Set(values[1])
		countLabel:Set(#values .. (#values == 1 and " item" or " items"))
	end

	local function selected()
		local e = byLabel[Flags.inv_item]
		if not e then notify("Pick an item first.") end
		return e
	end

	local function addSelected()
		local e = selected()
		if not e then return end
		local profile = getProfile()
		if not profile then notify("The game's inventory data isn't loaded yet.") return end
		if addItem(profile, e) then
			refreshGame(profile)
			notify("Added " .. e.name .. " to your inventory.", "Inventory", 3)
		else
			notify("You already have " .. e.name .. ".", "Inventory", 3)
		end
	end

	local function addAllShown()
		if working then return end
		local profile = getProfile()
		if not profile then notify("The game's inventory data isn't loaded yet.") return end
		if #shown == 0 then notify("Nothing is listed.") return end
		working = true
		local new, had = 0, 0
		for i, e in ipairs(shown) do
			if not running() then break end
			if addItem(profile, e) then new += 1 else had += 1 end
			if i % 20 == 0 then task.wait() end -- the game builds a screen entry for each one
		end
		refreshGame(profile)
		working = false
		notify(string.format("Added %d items (you already had %d).", new, had), "Inventory", 4)
	end

	-- Equipping is local too: it sets what the game thinks is equipped and tells its equip screen (the
	-- same two steps the game's own EquipItem takes), but never sends the server anything.
	local function equipEntry(e)
		local profile = getProfile()
		if not (profile and profile.Weapons and profile.Weapons.Equipped) then
			notify("The game's inventory data isn't loaded yet.")
			return
		end
		if addItem(profile, e) then refreshGame(profile) end
		local itemType = e.info.ItemType
		if originalEquipped[itemType] == nil then originalEquipped[itemType] = profile.Weapons.Equipped[itemType] end
		profile.Weapons.Equipped[itemType] = e.key
		local ok, equip = pcall(require, equipModule)
		if ok and type(equip) == "table" and equip.EquippedChanged then equip.EquippedChanged:Fire(itemType, e.key) end
		skinChoice[itemType] = e
		notify(e.name .. " is shown as your equipped " .. itemType:lower() .. ".", "Inventory", 4)
		applySkins(true) -- dresses the one in your hand (or puts a copy in your backpack) once its model has loaded
	end

	local function equipSelected()
		local e = selected()
		if not e then return end
		if e.dataCat ~= "Weapons" then notify("Only knives and guns can be equipped.") return end
		equipEntry(e)
	end

	-- The game's own Equip button on an item you added would tell the server about an item you don't own.
	-- So for items we added, that button is routed here instead; everything you really own goes through
	-- the game's real function untouched.
	do
		local ok, svc = pcall(require, equipModule)
		local realEquip = ok and type(svc) == "table" and svc.EquipItem
		if type(realEquip) == "function" then
			local function mine(category, key)
				for _, e in ipairs(added) do
					if e.dataCat == category and e.key == key then return e end
				end
			end
			pcall(function() if isreadonly and isreadonly(svc) then setreadonly(svc, false) end end)
			local hooked = pcall(function()
				svc.EquipItem = function(self, category, key)
					local e = mine(category, key)
					if not e then return realEquip(self, category, key) end
					if category == "Weapons" then
						equipEntry(e)
					else
						local profile = getProfile()
						if profile and profile[category] then profile[category].Equipped = { key } end
						if svc.EquippedChanged then svc.EquippedChanged:Fire(category, key) end
					end
				end
			end)
			if hooked then
				onUnload(function() pcall(function() svc.EquipItem = realEquip end) end)
			end
		end
	end

	local PickBox = InventoryTab:AddGroup("Pick An Item", "Left")
	PickBox:AddDropdown("inv_category", { Text = "Category", Values = CATEGORIES, Default = "Knives",
		Callback = function() refreshList() end })
	PickBox:AddTextbox("inv_search", { Text = "Search", Placeholder = "a name, then press Enter",
		Tooltip = "Narrows the list below. Add All uses only what's listed", Callback = function() refreshList() end })
	itemDropdown = PickBox:AddDropdown("inv_item", { Text = "Item", Values = {} })
	countLabel = PickBox:AddLabel("", { Color = Library.Theme.TextDim })
	if not catalogOk then
		PickBox:AddLabel("Couldn't read the game's item database.", { Color = Library.Theme.TextDim })
	end

	local AddBox = InventoryTab:AddGroup("Your Inventory", "Right")
	AddBox:AddButton({ Text = "Add Item", Tooltip = "Puts the selected item in your inventory screen", Callback = addSelected })
	AddBox:AddButton({ Text = "Add All Listed", Tooltip = "Adds every item in the list, including the search results", Callback = function() task.spawn(addAllShown) end })
	AddBox:AddButton({ Text = "Equip Item (Knife / Gun)", Tooltip = "Equips it: dresses your knife or gun, or puts a copy in your backpack when you have none (your screen only)", Callback = equipSelected })
	AddBox:AddButton({ Text = "Show My Real Weapons", Tooltip = "Takes the skins off the knife and gun in your hand", Callback = function()
		local profile = getProfile()
		if profile then restoreEquipped(profile) end
		clearAllSkins()
		notify("Showing your real weapons.", "Inventory", 3)
	end })
	AddBox:AddDivider()
	AddBox:AddButton({ Text = "Remove What I Added", Callback = function()
		local n = removeAdded()
		notify(n > 0 and ("Removed " .. n .. " items.") or "Nothing to remove.", "Inventory", 3)
	end })
	AddBox:AddLabel("Only you see this. Equip an added knife or gun here or with the game's own Equip button. It dresses the one in your hand, or lands in your backpack when you have none. Trades and your real weapon are unchanged.", { Color = Library.Theme.TextDim })

	refreshList()
end

loader:Step("Building the settings panel...")
------------------------------------------------------------------------
-- Settings (menu controls are UI, so they actually work)
------------------------------------------------------------------------
local Settings = Window:AddTab("Settings")

local Menu = Settings:AddGroup("Menu", "Left")
Menu:AddKeybind("menu_key", {
	Text = "Toggle UI",
	Default = Library.ToggleKey,
	Changed = function(key)
		if key and key.EnumType == Enum.KeyCode then
			Library.ToggleKey = key
			Library:_updateHint()
		end
	end,
})
Menu:AddDropdown("theme", { Text = "Theme", Values = Library.ThemeOrder, Default = themeName, Callback = function(v)
	if v == themeName then return end
	writeTheme(v)
	notify("Theme set to " .. v .. ". Re-run the script to apply it.", nil, 6)
end })
Menu:AddToggle("ui_sounds", { Text = "Sound Effects", Default = true, Tooltip = "The hover and click sounds on buttons" })
Menu:AddDivider()
Menu:AddButton({ Text = "Test Notification", Callback = function()
	Library:Notify("Murderer", "This is what a role alert looks like.", 5)
end })
Menu:AddButton({ Text = "Unload", Callback = function() Library:Unload() end })

local Config = Settings:AddGroup("Config", "Left")
local configLabel = Config:AddLabel("Settings save automatically.", { Color = Library.Theme.TextDim })
local resetButton = Config:AddButton({ Text = "Reset To Defaults" })

local About = Settings:AddGroup("About", "Right")
About:AddLabel(NAME .. " v" .. VERSION, { Bold = true })
About:AddLabel("Murder Mystery 2", { Color = Library.Theme.TextDim })
About:AddDivider()
About:AddLabel("X and _ shrink the window into a small bar. Click the bar to open it again. Unload stops the script.")

loader:Step("Building the Main tab...")
------------------------------------------------------------------------
-- Main: the features you reach for most, in one place. Every control here is a twin of one on its own
-- tab: change either and the other follows, so nothing is duplicated, just shown in two places.
------------------------------------------------------------------------
do
	-- a control for `flag` on the Main tab that stays in step with the original
	local function twin(group, kind, flag, o)
		local real = Options[flag]
		if not real then return end
		local mainFlag = "main_" .. flag
		State.mainFlags[mainFlag] = true -- the original is what gets saved
		o.Default = real.Value
		local ctl
		if kind == "toggle" then ctl = group:AddToggle(mainFlag, o)
		elseif kind == "slider" then ctl = group:AddSlider(mainFlag, o)
		elseif kind == "keybind" then ctl = group:AddKeybind(mainFlag, o)
		else ctl = group:AddDropdown(mainFlag, o) end
		ctl:OnChanged(function(v) if real.Value ~= v then real:Set(v) end end)
		real:OnChanged(function(v) if ctl.Value ~= v then ctl:Set(v) end end)
		return ctl
	end

	local Esp = MainTab:AddGroup("ESP", "Left")
	twin(Esp, "toggle", "esp_enabled", { Text = "ESP", Tooltip = "Master switch for all ESP" })
	twin(Esp, "toggle", "esp_murderer", { Text = "Murderer" })
	twin(Esp, "toggle", "esp_sheriff", { Text = "Sheriff / Hero" })
	twin(Esp, "toggle", "esp_innocent", { Text = "Innocents" })
	twin(Esp, "toggle", "gun_esp", { Text = "Dropped Gun" })
	twin(Esp, "toggle", "coin_esp", { Text = "Coins" })

	local GunBox = MainTab:AddGroup("Dropped Gun", "Left")
	twin(GunBox, "toggle", "grab_gun", { Text = "Auto Grab Gun", Tooltip = "Grabs the gun the moment it drops" })
	twin(GunBox, "toggle", "gun_notify", { Text = "Notify When Dropped" })
	GunBox:AddButton({ Text = "Grab Gun Now", Callback = State.actions.grabGun })
	GunBox:AddButton({ Text = "Teleport To Gun", Callback = tpGun })

	local Farm = MainTab:AddGroup("Autofarm", "Left")
	twin(Farm, "toggle", "autofarm_enabled", { Text = "Autofarm", Tooltip = "Master switch for every autofarm feature" })
	twin(Farm, "toggle", "coin_farm", { Text = "Auto Collect Coins" })

	local Escape = MainTab:AddGroup("Escape", "Left")
	twin(Escape, "keybind", "safe_spot_key", { Text = "Safe Spot Key" })
	Escape:AddLabel("Press it to teleport up and away when you need to get out of a situation. Press it again to come back. The autofarm parks there by itself when it's done.", { Color = Library.Theme.TextDim })

	local Fight = MainTab:AddGroup("Combat", "Right")
	twin(Fight, "toggle", "combat_enabled", { Text = "Combat", Tooltip = "Master switch for every combat feature" })
	twin(Fight, "toggle", "silent_aim", { Text = "Silent Aim", Tooltip = "Gun shots land on the murderer wherever you click" })
	twin(Fight, "toggle", "auto_shoot", { Text = "Auto Shoot Murderer" })
	twin(Fight, "dropdown", "aim_target", { Text = "Aim Part", Values = { "Head", "Torso" } })
	twin(Fight, "toggle", "knife_aura", { Text = "Knife Aura", Tooltip = "Stabs everyone inside the aura range" })
